// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { AreaChart } from "@/registry/erbium/charts/area-chart";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



import StackedExample from "./variants/stacked";



const meta = {
  component: AreaChart,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Area charts take the same props as the [Line Chart](/docs/charts/line-chart), plus `stacked` and `fill`. The default `gradient` fill fades each series toward the baseline in its own color.

```tsx
import { AreaChart } from "@/registry/erbium/charts/area-chart";

<AreaChart ariaLabel="Visitors by month" data={visitors} index="month" series={devices} stacked />;
```

Unstacked areas overlap, so keep them to two or three series. When exact values matter more than shape, use a line chart or a table.",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof AreaChart>;

export default { ...meta, title: "Charts/Area Chart",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  axis: boolean;
  curve: "smooth" | "linear" | "step";
  fill: "gradient" | "solid";
  grid: boolean;
  legend: boolean;
  stacked: boolean;
  tooltip: boolean;
}> = {
  argTypes: {
    axis: { control: "boolean" },
    curve: { control: "inline-radio", options: ["smooth", "linear", "step"] },
    fill: { control: "inline-radio", options: ["gradient", "solid"] },
    grid: { control: "boolean" },
    legend: { control: "boolean" },
    stacked: { control: "boolean" },
    tooltip: { control: "boolean" },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { AreaChart } from "@/registry/erbium/charts/area-chart";
import { devices, shortMonth, visitors } from "../examples/data";

export const defaultProps = {
  axis: true,
  curve: "smooth",
  fill: "gradient",
  grid: true,
  legend: true,
  stacked: false,
  tooltip: true,
} satisfies {
  axis: boolean;
  curve: "smooth" | "linear" | "step";
  fill: "gradient" | "solid";
  grid: boolean;
  legend: boolean;
  stacked: boolean;
  tooltip: boolean;
};

export default function AreaChartPlaygroundExample(
  args: {
    axis: boolean;
    curve: "smooth" | "linear" | "step";
    fill: "gradient" | "solid";
    grid: boolean;
    legend: boolean;
    stacked: boolean;
    tooltip: boolean;
  } = defaultProps,
) {
  return (
    <div className="w-full p-4">
      <AreaChart
        ariaLabel="Visitors by month and device"
        data={visitors}
        index="month"
        indexFormat={shortMonth}
        series={devices}
        initialWidth={640}
        {...args}
      />
    </div>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

export const Stacked: Story = {
  parameters: {
    docs: {
      description: { story: "Stacked areas keep the total on the top edge and give each series a layer of its own thickness." },
      source: { code: "import { AreaChart } from "@/registry/erbium/charts/area-chart";
import { devices, shortMonth, visitors } from "../examples/data";

export default function AreaChartStackedExample() {
  return (
    <div className="w-full p-4">
      <AreaChart
        ariaLabel="Visitors by month, stacked by device"
        data={visitors}
        index="month"
        indexFormat={shortMonth}
        series={devices}
        stacked
        initialWidth={640}
      />
    </div>
  );
}
" },
    },
  },
  render: StackedExample,
};

import type { ChartValue } from "@tanstack/charts";
import { formatChartIndex } from "@/registry/erbium/charts/chart";

export const visitors = [
  { desktop: 186, mobile: 80, month: "January" },
  { desktop: 305, mobile: 200, month: "February" },
  { desktop: 237, mobile: 120, month: "March" },
  { desktop: 73, mobile: 190, month: "April" },
  { desktop: 209, mobile: 130, month: "May" },
  { desktop: 214, mobile: 140, month: "June" },
];

export const devices = [
  { key: "desktop", label: "Desktop" },
  { key: "mobile", label: "Mobile" },
] as const;

export const shortMonth = (value: ChartValue) => formatChartIndex(value).slice(0, 3);

import { AreaChart } from "@/registry/erbium/charts/area-chart";
import { devices, shortMonth, visitors } from "../examples/data";

export const defaultProps = {
  axis: true,
  curve: "smooth",
  fill: "gradient",
  grid: true,
  legend: true,
  stacked: false,
  tooltip: true,
} satisfies {
  axis: boolean;
  curve: "smooth" | "linear" | "step";
  fill: "gradient" | "solid";
  grid: boolean;
  legend: boolean;
  stacked: boolean;
  tooltip: boolean;
};

export default function AreaChartPlaygroundExample(
  args: {
    axis: boolean;
    curve: "smooth" | "linear" | "step";
    fill: "gradient" | "solid";
    grid: boolean;
    legend: boolean;
    stacked: boolean;
    tooltip: boolean;
  } = defaultProps,
) {
  return (
    <div className="w-full p-4">
      <AreaChart
        ariaLabel="Visitors by month and device"
        data={visitors}
        index="month"
        indexFormat={shortMonth}
        series={devices}
        initialWidth={640}
        {...args}
      />
    </div>
  );
}

import { AreaChart } from "@/registry/erbium/charts/area-chart";
import { devices, shortMonth, visitors } from "../examples/data";

export default function AreaChartStackedExample() {
  return (
    <div className="w-full p-4">
      <AreaChart
        ariaLabel="Visitors by month, stacked by device"
        data={visitors}
        index="month"
        indexFormat={shortMonth}
        series={devices}
        stacked
        initialWidth={640}
      />
    </div>
  );
}

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);
